const COOKING_COMPAT_REMOVALS = ["delightful:integration/create/filling/long_prickly_pear_juice", "delightful:integration/create/filling/prickly_pear_juice", "farmersrespite:filling/melon_juice"]
ServerEvents.recipes(event => {
  COOKING_COMPAT_REMOVALS.forEach(id => event.remove({ id: id }))
  Object.keys(COOKING_COMPAT_RECIPES).forEach(id => {
    event.remove({ id: id })
    event.custom(COOKING_COMPAT_RECIPES[id]).id(id)
  })
})
